	match upgrade_id:
		\"speed_up\":
			speed += 50.0
		\"fire_rate\":
			shoot_cooldown = maxf(0.04, shoot_cooldown - 0.04)
		\"damage_up\":
			bullet_damage += 5
		\"bullet_speed\":
			bullet_speed += 150.0
		\"max_health\":
